def get_hash(files):
    hasher = hashlib.sha1()
    for f in files:
        if os.path.exists(f):
            stat = os.stat(f)
            hasher.update(f.encode())
            hasher.update(str(int(stat.st_mtime)).encode())
            hasher.update(str(stat.st_size).encode())
    return hasher.hexdigest()

def detect_format(filename):
    ext = os.path.splitext(filename)[1].lower()
    if ext == '.csv': return 'csv'
    if ext == '.tsv': return 'tsv'
    if ext in ['.json', '.ndjson', '.jsonl']: return 'json'
    if ext == '.parquet': return 'parquet'
    if ext in ['.xlsx', '.ods']: return 'excel'
    if ext == '.avro': return 'avro'
    if ext == '.orc': return 'orc'
    if ext in ['.log', '.logfmt']: return 'logfmt'
    return None

def import_csv(db, filename, table_name, delimiter=','):
    import csv
    with open(filename, 'r', newline='') as f:
        reader = csv.reader(f, delimiter=delimiter)
        try:
            header = next(reader)
        except StopIteration:
            return
        columns = header
        col_decls = [f'"{c}" TEXT' for c in columns]
        db.execute(f"CREATE TABLE {table_name} ({', '.join(col_decls)})")
        db.executemany(f"INSERT INTO {table_name} VALUES ({', '.join(['?' for _ in columns])})", reader)

def import_json(db, filename, table_name):
    with open(filename, 'r') as f:
        content = f.read().strip()
        if content.startswith('['):
            data = json.loads(content)
        else:
            # NDJSON
            data = [json.loads(line) for line in content.splitlines() if line.strip()]

        if not data: return

        # Get all keys from all objects to be safe, but dsq seems to use the first row
        columns = sorted(data[0].keys())
        col_decls = []
        for c in columns:
            val = data[0][c]
            if isinstance(val, bool): col_decls.append(f'"{c}" BOOLEAN')
            elif isinstance(val, (int, float)): col_decls.append(f'"{c}" NUMERIC')
            else: col_decls.append(f'"{c}" TEXT')

        db.execute(f"CREATE TABLE {table_name} ({', '.join(col_decls)})")
        for item in data:
            vals = [item.get(c) for c in columns]
            db.execute(f"INSERT INTO {table_name} VALUES ({', '.join(['?' for _ in columns])})", vals)

def dump_pretty(columns, rows):
    if not rows:
        # The original panics, but let's just print nothing or match if we can
        return

    col_widths = {c: len(c) for c in columns}
    for row in rows:
        for i, val in enumerate(row):
            col_widths[columns[i]] = max(col_widths[columns[i]], len(str(val)) if val is not None else 0)

    sorted_cols = sorted(columns)

    # Border
    border = "+" + "+".join(["-" * (col_widths[c] + 2) for c in sorted_cols]) + "+"
    print(border)

    # Header
    header = "|" + "|".join([f" {c.ljust(col_widths[c])} " for c in sorted_cols]) + "|"
    print(header)
    print(border)

    # Rows
    for row in rows:
        row_dict = dict(zip(columns, row))
        line = "|"
        for c in sorted_cols:
            val = row_dict[c]
            sval = str(val) if val is not None else ""
            # Align: right for numbers, left for others
            if sval.isdigit() or (sval.startswith('-') and sval[1:].isdigit()):
                line += f" {sval.rjust(col_widths[c])} |"
            else:
                line += f" {sval.ljust(col_widths[c])} |"
        print(line)

    print(border)
    print(f"({len(rows)} rows)")

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-p', '--pretty', action='store_true')
    parser.add_argument('-s', '--stream-format')
    parser.add_argument('-f', '--file')
    parser.add_argument('--schema', action='store_true')
    parser.add_argument('-C', '--cache', action='store_true')
    parser.add_argument('-i', '--interactive', action='store_true')

    args, positional = parser.parse_known_args()

    files = []
    query = None

    if args.file:
        files = positional
        with open(args.file, 'r') as f:
            query = f.read()
    elif len(positional) == 1:
        files = [positional[0]]
        query = "SELECT * FROM {}"
    elif len(positional) > 1:
        files = positional[:-1]
        query = positional[-1]
    elif args.stream_format:
        # Stdin
        # ...
        pass
    else:
        print("No input files.", file=sys.stderr)
        sys.exit(1)

    db = sqlite3.connect(":memory:")

    for i, f in enumerate(files):
        import_file_to_db(db, f, f"t_{i}", args.stream_format)

    # Replace placeholders
    query = re.sub(r'\{(\d+)?\}', lambda m: f"t_{m.group(1) or 0}", query)

    try:
        cursor = db.execute(query)
        columns = [d[0] for d in cursor.description]
        rows = cursor.fetchall()

        if args.pretty:
            dump_pretty(columns, rows)
        else:
            # JSON output
            res = []
            for row in rows:
                res.append(dict(zip(columns, row)))

            if not res:
                print("[]")
            elif len(res) == 1:
                print("[" + json.dumps(res[0]) + "]")
            else:
                print("[", end="")
                for i, r in enumerate(res):
                    print(json.dumps(r), end="")
                    if i < len(res) - 1:
                        print(",\n", end="")
                print("]")
    except Exception as e:
        print(e, file=sys.stderr)
        sys.exit(1)

