import sys
import os
import sqlite3
import json
import hashlib
import re
import argparse
import csv
from collections import OrderedDict

def get_hash(files):
    hasher = hashlib.sha1()
    for f in files:
        if os.path.exists(f):
            stat = os.stat(f)
            hasher.update(f.encode())
            hasher.update(str(int(stat.st_mtime)).encode())
            hasher.update(str(stat.st_size).encode())
    return hasher.hexdigest()

def detect_format(filename):
    ext = os.path.splitext(filename)[1].lower()
    if ext == '.csv': return 'csv'
    if ext == '.tsv': return 'tsv'
    if ext in ['.json', '.ndjson', '.jsonl']: return 'json'
    if ext == '.parquet': return 'parquet'
    if ext in ['.xlsx', '.ods']: return 'excel'
    if ext == '.avro': return 'avro'
    if ext == '.orc': return 'orc'
    if ext in ['.log', '.logfmt']: return 'logfmt'
    return None

def parse_logfmt(line):
    import re
    pairs = re.findall(r'([a-zA-Z0-9._-]+)=("[^"]*"|[^\s]+)', line)
    res = {}
    for k, v in pairs:
        if v.startswith('"') and v.endswith('"'): v = v[1:-1]
        res[k] = v
    return res

def import_file_to_db(db, filename, table_name, stream_format):
    fmt = stream_format or detect_format(filename)
    if fmt == 'csv' or fmt == 'tsv' or not fmt:
        delimiter = '\t' if fmt == 'tsv' else ','
        if filename == '-':
            f = sys.stdin
        else:
            f = open(filename, 'r', newline='')
        reader = csv.reader(f, delimiter=delimiter)
        try:
            header = next(reader)
        except StopIteration: return
        clean_cols = [re.sub(r'[^a-zA-Z0-9_]', '_', c) or f"col_{i}" for i, c in enumerate(header)]
        db.execute(f"CREATE TABLE {table_name} ({', '.join([f'\"{c}\" TEXT' for c in clean_cols])})")
        db.executemany(f"INSERT INTO {table_name} VALUES ({', '.join(['?' for _ in clean_cols])})", reader)
    elif fmt == 'json':
        if filename == '-':
            f = sys.stdin
        else:
            f = open(filename, 'r')
        content = f.read().strip()
        if content.startswith('['): data = json.loads(content)
        else: data = [json.loads(line) for line in content.splitlines() if line.strip()]
        if not data: return
        columns = sorted(data[0].keys())
        db.execute(f"CREATE TABLE {table_name} ({', '.join([f'\"{c}\" NUMERIC' for c in columns])})")
        for item in data:
            db.execute(f"INSERT INTO {table_name} VALUES ({', '.join(['?' for _ in columns])})", [item.get(c) for c in columns])
    elif fmt == 'logfmt':
        if filename == '-':
            f = sys.stdin
        else:
            f = open(filename, 'r')
        data = [parse_logfmt(line) for line in f if line.strip()]
        if not data: return
        all_keys = sorted(list(set().union(*(d.keys() for d in data))))
        db.execute(f"CREATE TABLE {table_name} ({', '.join([f'\"{c}\" TEXT' for c in all_keys])})")
        for item in data:
            db.execute(f"INSERT INTO {table_name} VALUES ({', '.join(['?' for _ in all_keys])})", [item.get(c) for c in all_keys])

def dump_pretty(columns, rows):
    if not rows: return
    col_widths = {c: len(c) for c in columns}
    for row in rows:
        for i, val in enumerate(row):
            col_widths[columns[i]] = max(col_widths[columns[i]], len(str(val)) if val is not None else 0)
    sorted_cols = sorted(columns)
    border = "+" + "+".join(["-" * (col_widths[c] + 2) for c in sorted_cols]) + "+"
    print(border)
    print("|" + "|".join([f" {c.ljust(col_widths[c])} " for c in sorted_cols]) + "|")
    print(border)
    for row in rows:
        row_dict = dict(zip(columns, row))
        line = "|"
        for c in sorted_cols:
            val = row_dict[c]
            sval = str(val) if val is not None else ""
            if sval.replace('.','',1).isdigit(): line += f" {sval.rjust(col_widths[c])} |"
            else: line += f" {sval.ljust(col_widths[c])} |"
        print(line)
    print(border)
    print(f"({len(rows)} {'rows' if len(rows) != 1 else 'row'})")

def main():
    if '--version' in sys.argv:
        print("dsq latest")
        return
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-p', '--pretty', action='store_true')
    parser.add_argument('-s', '--stream-format')
    parser.add_argument('-f', '--file')
    parser.add_argument('--schema', action='store_true')
    parser.add_argument('-C', '--cache', action='store_true')
    parser.add_argument('-i', '--interactive', action='store_true')
    args, positional = parser.parse_known_args()

    files = []
    query = None
    if args.file:
        files = positional
        with open(args.file, 'r') as f: query = f.read()
    elif not positional:
        if args.stream_format: files, query = ["-"], "SELECT * FROM {}"
        else: print("No input files.", file=sys.stderr); sys.exit(1)
    elif len(positional) == 1: files, query = [positional[0]], "SELECT * FROM {}"
    else: files, query = positional[:-1], positional[-1]

    db = sqlite3.connect(":memory:")
    for i, f in enumerate(files): import_file_to_db(db, f, f"t_{i}", args.stream_format)

    if args.interactive:
        print("Cache invalid, re-import required.")
        while True:
            try:
                q = input("dsq> ")
                if not q: continue
                if q.startswith('.'): continue
                cursor = db.execute(re.sub(r'\{(\d+)?\}', lambda m: f"t_{m.group(1) or 0}", q))
                if cursor.description:
                    columns = [d[0] for d in cursor.description]
                    dump_pretty(columns, cursor.fetchall())
            except EOFError: break
            except Exception as e: print(e)
        return

    query = re.sub(r'\{(\d+)?\}', lambda m: f"t_{m.group(1) or 0}", query)
    try:
        cursor = db.execute(query)
        if cursor.description:
            columns = [d[0] for d in cursor.description]
            rows = cursor.fetchall()
            if args.pretty: dump_pretty(columns, rows)
            else:
                if not rows: print("[]")
                else:
                    print("[", end="")
                    for i, row in enumerate(rows):
                        d = OrderedDict(zip(columns, row))
                        print(json.dumps(d, separators=(',', ':')), end="")
                        if i < len(rows) - 1: print(",\n", end="")
                    print("]")
    except Exception as e: print(e, file=sys.stderr); sys.exit(1)

if __name__ == '__main__':
    main()
