            try:
                q = input("dsq> ")
                if not q: continue
                cursor = db.execute(re.sub(r'\{(\d+)?\}', lambda m: "t_" + (m.group(1) or "0"), q))
                if cursor.description: dump_pretty([d[0] for d in cursor.description], cursor.fetchall())
            except EOFError: break
            except Exception as e: print(e)
        return
    query = re.sub(r'\{(\d+)?\}', lambda m: "t_" + (m.group(1) or "0"), query)
    try:
        cursor = db.execute(query)
        if cursor.description:
            columns, rows = [d[0] for d in cursor.description], cursor.fetchall()
            if args.pretty: dump_pretty(columns, rows)
            else:
                if not rows: print("[]")
                else:
                    print("[", end="")
                    for i, row in enumerate(rows):
                        print(json.dumps(OrderedDict(zip(columns, row)), separators=(',', ':')), end="")
                        if i < len(rows) - 1: print(",\n", end="")
                    print("]")
    except Exception as e: print(e, file=sys.stderr); sys.exit(1)

